<script setup lang="ts">
import { Upload, Search, ImagePlus, MoreHorizontal, Trash2, Pencil, Download, Image, Crop } from 'lucide-vue-next'
import type { Asset } from '@qinbian/shared'
const cropping=ref<Asset|null>(null)
const ctx=useQinbian(),items=ref<Asset[]>([]),query=ref(''),uploading=ref(false),dragging=ref(false),fileInput=ref<HTMLInputElement>(),preview=ref<Asset|null>(null),renaming=ref<Asset|null>(null),newName=ref('')
const filtered=computed(()=>items.value.filter(a=>a.name.toLowerCase().includes(query.value.toLowerCase())))
async function refresh(){items.value=await apiFetch('/api/assets')};onMounted(()=>refresh().catch(ctx.error))
async function upload(files:File[]){if(!files.length)return;uploading.value=true;try{for(const file of files){const body=new FormData();body.append('file',file);await apiFetch('/api/assets',{method:'POST',body})}await refresh();ctx.notify('图片已收进素材库')}catch(e){ctx.error(e)}finally{uploading.value=false;if(fileInput.value)fileInput.value.value=''}}
async function rename(){if(!renaming.value||!newName.value.trim())return;try{await apiFetch('/api/assets/'+renaming.value.id,{method:'PATCH',body:{name:newName.value}});renaming.value=null;await refresh()}catch(e){ctx.error(e)}}
async function remove(a:Asset){if(!confirm('将这张图片移到回收站？'))return;try{await apiFetch('/api/assets/'+a.id,{method:'DELETE'});await refresh()}catch(e){ctx.error(e)}}
async function download(a:Asset){try{const blob=await apiFetch('/api/assets/'+a.id+'/file',{responseType:'blob'});downloadFile(blob,a.name)}catch(e){ctx.error(e)}}
async function cropped(a:Asset){cropping.value=null;await refresh();preview.value=items.value.find(i=>i.id===a.id)||a;ctx.notify('裁切副本已存入素材库')}
</script>
<template><div class="page" @dragover.prevent="dragging=true" @dragleave.prevent="dragging=false" @drop.prevent="dragging=false;upload(Array.from($event.dataTransfer?.files||[]))"><header class="page-heading"><div><h1>图片素材</h1></div><div class="heading-actions"><button class="btn primary" :disabled="uploading" @click="fileInput?.click()"><Upload :size="16"/>{{uploading?'正在上传…':'上传图片'}}</button><input ref="fileInput" type="file" hidden multiple accept="image/jpeg,image/png,image/webp,image/gif" @change="upload(Array.from(($event.target as HTMLInputElement).files||[]))"></div></header><div class="list-toolbar"><span class="small muted">{{items.length}} 张 · JPG、PNG、WebP、GIF，单张 20 MB 以内</span><label class="search-field"><Search :size="16"/><input v-model="query" placeholder="搜索图片" aria-label="搜索图片"></label></div><div v-if="dragging" class="drop-overlay"><Upload :size="40"/><h2>松开以上传</h2></div><div v-if="!filtered.length" class="empty-state"><ImagePlus :size="36"/><h3>{{query?'没有匹配的图片':'还没有图片'}}</h3><p v-if="!query">点击“上传图片”，或把文件拖到这里。</p></div><div class="asset-gallery"><article v-for="a in filtered" :key="a.id" class="asset-card"><button class="asset-image-button" :aria-label="'查看图片 '+a.name" @click="preview=a"><img :src="`/api/assets/${a.id}/thumbnail`" :alt="a.name" loading="lazy"><span v-if="a.mime==='image/gif'" class="gif-label">GIF</span></button><div class="asset-info"><h2 :title="a.name">{{a.name}}</h2><p>{{a.width}} × {{a.height}}<span>·</span>{{(a.bytes/1024/1024).toFixed(2)}} MB</p><div class="asset-bottom"><span class="small muted">{{a.builtin?'内置素材':a.references?.length?a.references.length+' 处引用':'未使用'}}</span><button class="icon-button" :aria-label="'重命名 '+a.name" @click="renaming=a;newName=a.name"><Pencil :size="13"/></button><button class="icon-button" :aria-label="'下载图片 '+a.name" @click="download(a)"><Download :size="14"/></button><button v-if="!a.builtin" class="icon-button" :aria-label="'删除图片 '+a.name" @click="remove(a)"><Trash2 :size="13"/></button></div></div></article></div><UiModal v-if="preview" :title="preview.name" wide @close="preview=null"><img class="asset-full-preview" :src="`/api/assets/${preview.id}/file`" :alt="preview.name"><div class="modal-actions"><button class="btn" @click="cropping=preview"><Crop :size="15"/>裁切为副本</button></div><div class="asset-reference-list"><h4>使用位置</h4><p v-if="!preview.references?.length" class="muted small">未被引用。</p><NuxtLink v-for="r in preview.references" :key="r.type+r.id" :to="r.type==='document'?'/documents/'+r.id:r.type==='resource'?'/resources/'+r.id:r.type==='asset'?'/assets':'/trash'">{{r.name}}</NuxtLink></div></UiModal><ImageCropper v-if="cropping" :asset-id="cropping.id" :spec="cropping.crop?.spec" @close="cropping=null" @apply="cropped"/><UiModal v-if="renaming" title="重命名图片" @close="renaming=null"><form class="form-stack" @submit.prevent="rename"><label>图片名称<input v-model="newName" required></label><div class="modal-actions"><button class="btn primary">保存</button></div></form></UiModal></div></template>
